60	// Amounts arrive as numbers such as 12.5 or 4.35 and are kept as whole cents, so sums never drift.
61	export function parseAmount(v) {
62	  if (typeof v !== 'number' || !TWO_DECIMALS.test(String(v))) throw new ValidationError(AMOUNT_MESSAGE)
63	  // Rounded, not truncated: 4.35 * 100 is 434.99999999999994 in floating point.
64	  const cents = Math.round(v * CENTS_PER_UNIT)
65	  if (cents < 1 || cents > MAX_AMOUNT_CENTS) throw new ValidationError(AMOUNT_MESSAGE)
66	  return cents
