75	// Who shares an expense: a non-empty list of members without repeats. Missing means every member, in group order.
76	export function parseSplit(v, members) {
77	  if (v === undefined) return [...members]
78	  if (!Array.isArray(v) || v.length === 0 || new Set(v).size !== v.length) throw new ValidationError(SPLIT_MESSAGE)
79	  if (!v.every(name => typeof name === 'string' && members.includes(name))) throw new ValidationError(SPLIT_MESSAGE)
80	  return [...v]
